# Public @function methods (also registered as @check)
# ------------------------------------------------------------------

@function
@check
async def quality(
    self,
    source: Annotated[
        dagger.Directory,
        DefaultPath("."),
        Doc("Repository root directory to run quality checks against."),
    ],
) -> str:
    """Run ruff lint, ruff format --check, and mypy."""
    return await self._run_quality(source)

@function
@check
async def security(
    self,
    source: Annotated[
        dagger.Directory,
        DefaultPath("."),
        Doc("Repository root directory to run security scans against."),
    ],
) -> str:
    """Run safety, bandit, and semgrep (custom + auto configs)."""
    return await self._run_security(source)

@function
@check
async def test(
    self,
    source: Annotated[
        dagger.Directory,
        DefaultPath("."),
        Doc("Repository root directory to run Django tests against."),
    ],
) -> str:
    """Django checks + migrations + pytest with coverage."""
    return await self._run_test(source)

@function
async def e2e(
    self,
    source: Annotated[
        dagger.Directory,
        DefaultPath("."),
        Doc("Repository root directory to run Playwright e2e tests against."),
    ],
) -> str:
    """Run Playwright smoke + auth suites against a live Django server.

    Exposed as a plain ``@function`` (not a ``@check``) because the
    Playwright suite is slow (~15m) and should be opt-in. Invoke via
    ``dagger call e2e`` or via ``dagger call ci --include-e2e=true``.
    """
    return await self._run_e2e(source)

@function
@check
async def docker_build(
    self,
    source: Annotated[
        dagger.Directory,
        DefaultPath("."),
        Doc("Repository root directory to build the Dockerfile from."),
    ],
) -> str:
    """Build the production Dockerfile and validate runtime checks."""
    return await self._run_docker_build(source)

@function
async def ci(
    self,
    source: Annotated[
        dagger.Directory,
        DefaultPath("."),
        Doc("Repository root directory to run the full CI pipeline against."),
    ],
    skip_security: Annotated[
        bool,
        Doc("Skip the security stage (useful for faster local iteration)."),
    ] = False,
    include_e2e: Annotated[
        bool,
        Doc("Include the e2e stage in the full CI run."),
    ] = False,
) -> str:
    """Run the full CI pipeline sequentially.

    Exposed as a plain ``@function`` (not a ``@check``) so that
    ``dagger check --failfast`` runs the individual stages in parallel
    instead of running them twice. Invoke this orchestrator explicitly
    via ``dagger call ci``.
    """
    results: list[str] = []
    results.append(await self._run_quality(source))
    if not skip_security:
        results.append(await self._run_security(source))
    results.append(await self._run_test(source))
    if include_e2e:
        results.append(await self._run_e2e(source))
    results.append(await self._run_docker_build(source))
    return "\n".join(results)

